--
-- Estructura de tabla para la tabla `ia_feedback`
--

DROP TABLE IF EXISTS `ia_feedback`;
CREATE TABLE IF NOT EXISTS `ia_feedback` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `interaction_id` bigint UNSIGNED NOT NULL,
  `user_id` bigint DEFAULT NULL,
  `feedback_tipo` varchar(50) NOT NULL,
  `feedback_texto` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ia_feedback_interaction` (`interaction_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `ia_interacciones`
--

DROP TABLE IF EXISTS `ia_interacciones`;
CREATE TABLE IF NOT EXISTS `ia_interacciones` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `pregunta` text NOT NULL,
  `intencion` varchar(255) NOT NULL,
  `entidad_tipo` varchar(100) DEFAULT NULL,
  `entidad_id` bigint DEFAULT NULL,
  `sql_generado` text,
  `tool_usada` varchar(120) DEFAULT NULL,
  `respuesta` text NOT NULL,
  `tiempo_ms` int DEFAULT NULL,
  `exito` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ia_interacciones_user_created` (`user_id`,`created_at`),
  KEY `idx_ia_interacciones_tool` (`tool_usada`),
  KEY `idx_ia_interacciones_intencion` (`intencion`(250))
) ENGINE=MyISAM AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

