(21, 1018372157, 'puntos del poblado', 'points_query', 'puntos', 258, NULL, 'consultar_puntos', 'Encontré 20 puntos relacionados con Poblado. Te muestro las coincidencias más relevantes.\nAlgunas coincidencias:\n- 12 Nights\n- 14 Urban\n- 1616 Hotel\n- 23 Hotel\n- 35th Station', 26, 1, '2026-05-20 09:00:43'),
