(23, 1018372157, 'que puedes hacer ?', 'capabilities_help', NULL, NULL, NULL, NULL, 'Puedo ayudarte a consultar reservas, tours, transfers, puntos, cupos y pagos. También puedo buscar entidades como Guatapé, Río Claro, una reserva por ID o un transfer. Además puedo mostrar acciones rápidas como Ver cupos, Ver reservas o Ver tour. Más adelante podré ayudarte con gráficos, listados de buses, borradores de reservas y alertas inteligentes.', 2, 1, '2026-05-20 09:05:39'),
(24, 1018372157, 'TG10146', 'short_entity_query', NULL, NULL, NULL, NULL, 'No encontré coincidencias operativas para esa búsqueda. Puedes preguntarme por reservas, tours, transfers, puntos, cupos o pagos.', 5, 0, '2026-05-20 09:06:11'),
