--
-- Estructura de tabla para la tabla `programacion_alertas`
--

DROP TABLE IF EXISTS `programacion_alertas`;
CREATE TABLE IF NOT EXISTS `programacion_alertas` (
  `Id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Programacion` bigint UNSIGNED NOT NULL,
  `Tipo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Detalle` text COLLATE utf8mb4_unicode_ci,
  `Creada_En` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Resuelta` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`Id`),
  KEY `idx_programacion_alertas_programacion` (`Id_Programacion`,`Resuelta`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

