-- Estructura de tabla para la tabla `programacion_buses`
--

DROP TABLE IF EXISTS `programacion_buses`;
CREATE TABLE IF NOT EXISTS `programacion_buses` (
  `Id_Bus_Prog` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Programacion` bigint UNSIGNED NOT NULL,
  `Placa_Display` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Capacidad` int NOT NULL DEFAULT '0',
  `Pasajeros_Total` int NOT NULL DEFAULT '0',
  `Guia` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Conductor` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DNI_Guia` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DNI_Conductor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Recorrido_Km` decimal(8,2) DEFAULT NULL,
  `Orden_Bus` int NOT NULL,
  PRIMARY KEY (`Id_Bus_Prog`),
  KEY `idx_programacion_buses_programacion` (`Id_Programacion`,`Orden_Bus`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

