DROP TABLE IF EXISTS `programacion_paradas`;
CREATE TABLE IF NOT EXISTS `programacion_paradas` (
  `Id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Bus_Prog` bigint UNSIGNED NOT NULL,
  `Orden_Parada` int NOT NULL,
  `Id_Punto_Snap` bigint UNSIGNED DEFAULT NULL,
  `Nombre_Snap` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Latitud_Snap` decimal(10,7) DEFAULT NULL,
  `Longitud_Snap` decimal(10,7) DEFAULT NULL,
  `Ruta_Snap` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Posicion_Snap` int DEFAULT NULL,
  `Pasajeros_Total_Snap` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`Id`),
  UNIQUE KEY `ux_programacion_paradas_bus_orden` (`Id_Bus_Prog`,`Orden_Parada`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `programacion_reservas`
--

DROP TABLE IF EXISTS `programacion_reservas`;
CREATE TABLE IF NOT EXISTS `programacion_reservas` (
  `Id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Bus_Prog` bigint UNSIGNED NOT NULL,
  `Id_Reserva` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Orden_En_Bus` int NOT NULL,
  `Num_Pasajeros_Snap` int NOT NULL DEFAULT '0',
  `Id_Tour_Snap` bigint UNSIGNED DEFAULT NULL,
  `Fecha_Tour_Snap` date DEFAULT NULL,
  `Estado_Snap` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Tipo_Reserva_Snap` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Nombre_Reportante_Snap` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Idioma_Reserva_Snap` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Observaciones_Snap` text COLLATE utf8mb4_unicode_ci,
  `Id_Punto_Principal_Snap` bigint UNSIGNED DEFAULT NULL,
  `Nombre_Punto_Principal_Snap` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Latitud_Principal_Snap` decimal(10,7) DEFAULT NULL,
  `Longitud_Principal_Snap` decimal(10,7) DEFAULT NULL,
  `Ruta_Principal_Snap` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Posicion_Principal_Snap` int DEFAULT NULL,
  `Requiere_Revision` tinyint(1) NOT NULL DEFAULT '0',
  `Motivo_Revision` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `ux_programacion_reservas_bus_reserva` (`Id_Bus_Prog`,`Id_Reserva`),
  KEY `idx_programacion_reservas_reserva` (`Id_Reserva`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `programacion_tours`
--

DROP TABLE IF EXISTS `programacion_tours`;
CREATE TABLE IF NOT EXISTS `programacion_tours` (
  `Id_Programacion` bigint UNSIGNED NOT NULL,
  `Id_Tour` bigint UNSIGNED NOT NULL,
  PRIMARY KEY (`Id_Programacion`,`Id_Tour`),
  KEY `idx_programacion_tours_tour` (`Id_Tour`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `puntos`
--

DROP TABLE IF EXISTS `puntos`;
CREATE TABLE IF NOT EXISTS `puntos` (
  `Id_Punto` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Nombre_Punto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Sector` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Direccion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ruta` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `posicion` int NOT NULL DEFAULT '0',
  `Latitud` decimal(10,7) DEFAULT NULL,
  `Longitud` decimal(10,7) DEFAULT NULL,
  PRIMARY KEY (`Id_Punto`),
  KEY `idx_puntos_ruta_pos` (`ruta`,`posicion`,`Id_Punto`)
) ENGINE=InnoDB AUTO_INCREMENT=632 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

